'use strict';
state.receipts??=[];state.aliases??={};
labels.expenses=['◷','Chi tiêu'];
let receiptDraft=null,receiptPhoto=null,receiptPhotoURL='',notesDraft=null,ocrBusy=false;
function spendingSummary(start){const receipts=receiptsInWeek(state,start);const actual=receipts.reduce((n,r)=>n+receiptTotal(r),0);return{receipts,actual,remaining:state.preferences.budget-actual}}
function renderExpenses(){const {receipts,actual,remaining}=spendingSummary(weekStart),history=priceHistory(state);const unallocated=receipts.reduce((n,r)=>n+Math.abs(r.total-r.items.reduce((m,i)=>m+i.total,0))+r.items.filter(i=>!i.ingredient&&!i.recipe&&i.kind!=='other').reduce((m,i)=>m+Math.abs(i.total),0),0);return heading('Chi tiêu, rõ ràng hơn','Từ hóa đơn đi chợ đến ngân sách và giá từng nguyên liệu.',`<button class="btn primary" data-feature="receipt-new">▧ Chụp / nhập hóa đơn</button>`)+`<div class="week-tools">${weekControls()}<div class="toolbar"><button class="btn small" data-feature="notes-import">▤ Nhập ghi chú</button><button class="btn small" data-feature="cloud-settings">☁ Đồng bộ Netlify</button></div></div><div class="stat-grid"><div class="card"><small>ĐÃ CHI THỰC TẾ</small><strong>${aud(actual)}</strong><small>${receipts.length} hóa đơn trong tuần</small></div><div class="card"><small>${remaining>=0?'CÒN TRONG NGÂN SÁCH':'VƯỢT NGÂN SÁCH'}</small><strong style="color:${remaining<0?'#ad6542':'inherit'}">${aud(Math.abs(remaining))}</strong><small>Mục tiêu ${aud(state.preferences.budget)}</small></div><div class="card"><small>CHƯA ĐỐI ỨNG / PHÂN BỔ</small><strong>${aud(unallocated)}</strong><small>Dòng chưa rõ + chênh tổng bill</small></div></div><div class="shopping-layout"><section><div class="section-heading"><h2>Hóa đơn tuần này</h2><small>Ngày mua quyết định tuần ghi nhận</small></div>${receipts.length?receipts.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article class="card receipt-card"><div><span class="receipt-symbol">▧</span><h3>${esc(r.store||'Cửa hàng chưa đặt tên')}</h3><small>${dateLabel(r.date)} · ${r.items.length} dòng · ${r.items.filter(i=>!i.ingredient&&!i.recipe&&i.kind!=='other').length} chưa đối ứng</small></div><div class="receipt-total"><b>${aud(r.total)}</b><button class="text-btn" data-feature="receipt-open" data-id="${r.id}">Xem / sửa ↗</button></div></article>`).join(''):'<div class="card empty"><span class="emoji">🧾</span><h3>Chưa có hóa đơn trong tuần</h3><p>Chụp bill hoặc dán nội dung để ghi khoản chi đầu tiên.</p><button class="btn primary" data-feature="receipt-new">Thêm hóa đơn</button></div>'}<div class="section-heading"><h2>Giá nguyên liệu có tăng không?</h2><span class="pill gray">Giá thực mua / kg, lít, quả</span></div><div class="card">${history.length?history.map(h=>`<div class="price-history-row"><div><b>${esc(INGREDIENTS[h.ingredient][0])}</b><small>${esc(h.store||'Chưa rõ cửa hàng')} · ${dateLabel(h.date)} · ${h.count} lần ghi nhận</small><small>${esc(h.label)}</small></div><div><b>${aud(h.value)} / ${h.unit}</b><span class="pill ${h.change>0?'orange':'gray'}">${h.change===null?'Cần thêm 1 lần mua':(h.change>0?'↑ ':h.change<0?'↓ ':'= ')+Math.abs(h.change).toFixed(1)+'%'}</span></div></div>`).join(''):'<p class="hint">Nhập khối lượng thực mua trên hóa đơn để so sánh đơn giá. Không suy ra giá/kg từ một gói chưa rõ trọng lượng.</p>'}<p class="hint topspace">So sánh hai lần mua gần nhất của cùng nguyên liệu tại cùng cửa hàng, theo dữ liệu bạn xác nhận. Quy cách, nhãn hàng và khuyến mãi có thể khác nhau; đây là biến động giá ghi nhận, không phải chỉ số lạm phát.</p></div></section><aside class="card budget-card"><h3>Bốn tuần gần đây</h3>${[3,2,1,0].map(n=>{const start=addDays(weekStart,-7*n),sum=spendingSummary(start).actual,width=Math.min(100,sum/state.preferences.budget*100);return `<div class="spend-week"><div><span>${dateLabel(start)} – ${dateLabel(addDays(start,6))}</span><b>${aud(sum)}</b></div><div class="progress"><span style="width:${width}%;background:${sum>state.preferences.budget?'#c58b58':'#55845e'}"></span></div></div>`}).join('')}<p>Chi thực tế lấy từ tổng hóa đơn. Danh sách đi chợ vẫn là dự toán riêng, không cộng chồng vào chi thực tế.</p><button class="btn full" data-feature="receipt-new">+ Ghi khoản mua</button></aside></div>`}
function matchingOptions(match){const[start,end]=shopDates(),needed=shopping(state,currentWeek(),start,end).filter(r=>r.qty>0&&!r.skip).map(r=>r.id);const planned=[...new Map(Object.values(currentWeek().days).flatMap(day=>Object.values(day).flatMap(m=>m.recipes)).map(r=>[r.id,r])).values()];const option=(id,name)=>`<option value="${esc(id)}" ${match===id?'selected':''}>${esc(name)}</option>`;return option('','Chưa đối ứng')+option('other','Chi tiêu khác / không phải nguyên liệu')+`<optgroup label="Nguyên liệu đang cần mua">${needed.map(id=>option(id,INGREDIENTS[id][0])).join('')}</optgroup><optgroup label="Nguyên liệu khác">${Object.entries(INGREDIENTS).filter(([id])=>!needed.includes(id)).map(([id,i])=>option(id,i[0])).join('')}</optgroup><optgroup label="Món ăn trong thực đơn">${planned.map(r=>option('recipe:'+r.id,r.name)).join('')}</optgroup>`}
function newReceipt(){receiptDraft={id:uid(),store:'',date:sydneyDate(),total:0,items:[],createdAt:new Date().toISOString(),editing:false};receiptPhoto=null;if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL='';receiptEditor()}
function receiptEditor(){const d=receiptDraft;if(!d)return;modal(d.editing?'Xem & sửa hóa đơn':'Chụp / nhập hóa đơn',`<div class="receipt-entry-tools"><button class="btn soft" data-feature="receipt-camera">▧ Chụp receipt</button><button class="btn" data-feature="receipt-file">Chọn ảnh</button><select class="input" id="ocr-language" aria-label="Ngôn ngữ hóa đơn" style="width:auto"><option value="eng">Tiếng Anh</option><option value="eng+vie">Anh + Việt</option></select></div><input type="file" id="receipt-camera-file" accept="image/*" capture="environment" hidden><input type="file" id="receipt-gallery-file" accept="image/*" hidden>${receiptPhotoURL?`<img class="receipt-image" src="${receiptPhotoURL}" alt="Ảnh hóa đơn đang đối chiếu">`:''}<p id="ocr-status" class="hint" role="status">Đọc chữ trên thiết bị; cần mạng để tải bộ OCR lần đầu. Kết quả là đề xuất, bạn kiểm tra trước khi lưu. Ảnh chưa được gửi đi tự động.</p><div class="field"><label for="receipt-raw">Hoặc dán / sửa nội dung hóa đơn</label><textarea id="receipt-raw" rows="5" placeholder="Chicken breast 500g 8.50&#10;Tomato 1kg 4.00&#10;TOTAL 12.50">${esc(d.raw||'')}</textarea></div><div class="toolbar"><button class="btn small" data-feature="receipt-parse">Đọc các dòng hóa đơn</button><button class="text-btn" data-feature="receipt-add-line">+ Nhập một dòng</button></div><div class="form-grid topspace"><div class="field"><label for="receipt-store">Cửa hàng</label><input id="receipt-store" maxlength="100" value="${esc(d.store)}" placeholder="Woolworths, Coles, chợ Việt…"></div><div class="field"><label for="receipt-date">Ngày mua</label><input id="receipt-date" type="date" value="${d.date}" required></div></div><div id="receipt-lines">${receiptLineRows()}</div><div class="receipt-reconcile"><div class="field"><label for="receipt-total">Tổng thực trả (AUD)</label><input id="receipt-total" type="number" min="0" max="999999" step="0.01" value="${d.total}" required></div><div><small>Tổng các dòng</small><b id="receipt-lines-total"></b></div><div><small>Chưa phân bổ / điều chỉnh</small><b id="receipt-difference"></b></div></div><p class="hint">Dòng giảm giá có thể nhập số tiền âm. Chênh lệch với tổng bill được giữ riêng; không tự sửa để trông khớp. Khối lượng không rõ có thể để trống, nhưng chưa so sánh được đơn giá.</p><label class="checked-label"><input id="receipt-mark-bought" type="checkbox" class="check" ${d.editing?'disabled':''}> Đánh dấu đã mua theo khối lượng thực đã đối ứng</label><p class="hint">Chỉ áp dụng cho nguyên liệu trong phạm vi danh sách đang xem, có khối lượng hợp lệ. Chưa tự cộng tồn kho; bạn dùng “Cất đồ đã mua” ở tab Đi chợ.</p>`,`<button class="btn" data-feature="receipt-add-line">+ Thêm dòng</button><button class="btn primary" data-feature="receipt-save">${d.editing?'Lưu chỉnh sửa':'Kiểm tra & lưu khoản chi'}</button>`,true);$('.modal').classList.add('receipt-modal');updateReceiptTotals()}
function receiptLineRows(){return receiptDraft.items.map((item,index)=>`<article class="receipt-line" data-index="${index}"><div class="receipt-line-top"><input class="input receipt-label" aria-label="Tên dòng ${index+1}" value="${esc(item.label)}" maxlength="200"><input class="input receipt-price" aria-label="Thành tiền dòng ${index+1}" type="number" step="0.01" min="-999999" max="999999" value="${item.total}"><button class="icon" data-feature="receipt-remove-line" data-index="${index}" aria-label="Bỏ dòng ${index+1}">×</button></div><div class="receipt-line-bottom"><div class="field"><label>Đối ứng ${item.confidence&&item.confidence!=='unknown'?'· đề xuất cần kiểm tra':''}</label><select class="input receipt-match" aria-label="Đối ứng dòng ${index+1}">${matchingOptions(item.match)}</select></div><div class="field"><label>Khối lượng thực</label><input class="input receipt-qty" aria-label="Khối lượng dòng ${index+1}" type="number" min="0.001" max="1000000" step="any" placeholder="Chưa rõ" value="${item.qty??''}"></div><div class="field"><label>Đơn vị</label><select class="input receipt-unit" aria-label="Đơn vị dòng ${index+1}">${[['','Chưa rõ'],['g','g'],['kg','kg'],['ml','ml'],['l','lít'],['quả','quả'],['pack','gói / hộp chưa rõ lượng']].map(([u,n])=>`<option value="${u}" ${item.unit===u?'selected':''}>${n}</option>`).join('')}</select></div></div></article>`).join('')||'<div class="empty"><p>Chọn ảnh hoặc dán nội dung, sau đó bấm “Đọc các dòng hóa đơn”.</p></div>'}
function collectReceipt(){if(!receiptDraft||!$('#receipt-store'))return;receiptDraft.store=$('#receipt-store').value.trim();receiptDraft.date=$('#receipt-date').value;receiptDraft.total=+$('#receipt-total').value;receiptDraft.raw=$('#receipt-raw').value;receiptDraft.markBought=$('#receipt-mark-bought')?.checked||false;$$('.receipt-line').forEach(el=>{const item=receiptDraft.items[+el.dataset.index];item.label=$('.receipt-label',el).value.trim();item.total=+$('.receipt-price',el).value;item.match=$('.receipt-match',el).value;item.qty=$('.receipt-qty',el).value===''?null:+$('.receipt-qty',el).value;item.unit=$('.receipt-unit',el).value})}
function updateReceiptTotals(){if(!receiptDraft||!$('#receipt-lines-total'))return;collectReceipt();const sum=receiptDraft.items.reduce((n,i)=>n+i.total,0);$('#receipt-lines-total').textContent=aud(sum);$('#receipt-difference').textContent=aud(receiptDraft.total-sum)}
let ocrScriptPromise=null;
function loadOCR(){if(window.Tesseract)return Promise.resolve();if(!ocrScriptPromise)ocrScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.0.0/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>{ocrScriptPromise=null;reject(Error('Không tải được OCR. Hãy thử lại khi có mạng hoặc dán nội dung hóa đơn.'))};document.head.append(script)});return ocrScriptPromise}
async function photoBlob(file){if(file.size>20000000)throw Error('Ảnh tối đa 20 MB. Hãy chụp lại gần và rõ nét.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Không đọc được ảnh. Dùng JPEG hoặc PNG.')),'image/jpeg',.88))}finally{URL.revokeObjectURL(url)}}
async function readReceiptPhoto(file){if(!file||ocrBusy)return;collectReceipt();const lang=$('#ocr-language')?.value||'eng';ocrBusy=true;let worker;const status=text=>{if($('#ocr-status'))$('#ocr-status').textContent=text};try{receiptPhoto=await photoBlob(file);if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL=URL.createObjectURL(receiptPhoto);status('Đang tải bộ đọc hóa đơn…');await loadOCR();worker=await Tesseract.createWorker(lang,1,{logger:info=>status(`${info.status==='recognizing text'?'Đang đọc chữ':info.status} · ${Math.round((info.progress||0)*100)}%`)});const result=await worker.recognize(receiptPhoto);receiptDraft.raw=result.data.text;const parsed=parseReceiptText(result.data.text,state);Object.assign(receiptDraft,{store:receiptDraft.store||parsed.store,date:parsed.date,total:parsed.total,items:parsed.items});receiptEditor();status(`Đã đọc ảnh · độ tin cậy OCR trung bình ${Math.round(result.data.confidence||0)}%. Kiểm tra tên, khối lượng, ngày và tổng tiền trước khi lưu.`)}catch(error){toast(error.message||'Chưa đọc được ảnh. Bạn có thể dán chữ hoặc nhập thủ công.',true);status('OCR chưa hoàn tất. Không có khoản chi nào được tự ghi nhận.')}finally{ocrBusy=false;if(worker)await worker.terminate()}}
function photoDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('bep-receipt-photos',1);request.onupgradeneeded=()=>request.result.createObjectStore('photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function localPhoto(id,value){const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',value===undefined?'readonly':'readwrite'),store=tx.objectStore('photos');const r=value===undefined?store.get(id):store.put(value,id);let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function saveReceipt(confirmed=false){collectReceipt();const d=receiptDraft;if(!d||ocrBusy){toast('Đợi đọc ảnh hoàn tất trước khi lưu.',true);return}if(!d.date||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isFinite(d.total)||d.total<0||d.total>999999||!d.items.length||d.items.some(i=>!i.label||!Number.isFinite(i.total)||Math.abs(i.total)>999999||i.qty!==null&&(!Number.isFinite(i.qty)||i.qty<=0||i.qty>1e6))){toast('Kiểm tra ngày, tổng tiền, tên dòng và số lượng hợp lệ.',true);return}const delta=d.total-d.items.reduce((n,i)=>n+i.total,0);if(!confirmed&&Math.abs(delta)>.02){modal('Kiểm tra chênh lệch hóa đơn',`<p>Tổng thực trả ${aud(d.total)} khác tổng các dòng ${aud(d.total-delta)}.</p><div class="callout">Chênh ${aud(delta)} sẽ được ghi riêng, chưa phân bổ vào nguyên liệu. Kiểm tra lại nếu đây là lỗi đọc chữ.</div>`,`<button class="btn" data-feature="receipt-back">Sửa hóa đơn</button><button class="btn primary" data-feature="receipt-save-confirm">Lưu với chênh lệch này</button>`);return}const items=d.items.map(i=>({id:i.id,label:i.label,total:i.total,ingredient:Object.hasOwn(INGREDIENTS,i.match)?i.match:null,recipe:i.match.startsWith('recipe:')?i.match.slice(7):null,kind:i.match==='other'?'other':!i.match?'pending':'matched',quantity:Object.hasOwn(INGREDIENTS,i.match)?canonicalQuantity(i.qty,i.unit,i.match):null,enteredQty:i.qty,enteredUnit:i.unit}));const record={id:d.id,store:d.store||'Chưa đặt tên cửa hàng',date:d.date,total:d.total,items,createdAt:d.createdAt,updatedAt:new Date().toISOString(),hasPhoto:!!receiptPhoto||!!d.hasPhoto,raw:d.raw||''};const fingerprint=normalizeText(record.store)+'|'+record.date+'|'+record.total+'|'+items.map(i=>normalizeText(i.label)+':'+i.total).join('|');record.fingerprint=fingerprint;if(state.receipts.some(r=>r.id!==record.id&&r.fingerprint===fingerprint)){toast('Hóa đơn giống bản đã lưu. Kiểm tra để tránh ghi chi tiêu hai lần.',true);return}const mark=d.markBought;for(const i of d.items)if(i.match)state.aliases[normalizeText(i.label)]=i.match;const existing=state.receipts.findIndex(r=>r.id===record.id);if(existing>=0)state.receipts[existing]=record;else state.receipts.push(record);if(mark){const[start,end]=shopDates(),week=currentWeek(),rows=shopping(state,week,start,end);for(const i of items){if(i.ingredient&&i.quantity&&rows.some(r=>r.id===i.ingredient)){const siblings=items.filter(x=>x.ingredient===i.ingredient&&x.quantity);const qty=siblings.reduce((n,x)=>n+x.quantity,0);setPurchaseQuantity(week,start,end,i.ingredient,qty);week.bought[i.ingredient]=qty}}}log(`Ghi hóa đơn ${record.store}: ${aud(record.total)}`);const photo=receiptPhoto;receiptDraft=null;receiptPhoto=null;save('Đã ghi chi tiêu thực tế.');closeModal();view='expenses';location.hash='expenses';render();if(photo){try{await localPhoto(record.id,{blob:photo,uploaded:false});if(cloudConnection.connected)uploadPendingPhotos()}catch(error){toast('Đã lưu khoản chi, nhưng chưa lưu được ảnh trên thiết bị.',true)}}}
async function openReceipt(id){const r=state.receipts.find(r=>r.id===id);if(!r)return;receiptPhoto=null;receiptDraft={...clone(r),editing:true,items:r.items.map(i=>({id:i.id,label:i.label,total:i.total,match:i.ingredient||i.recipe&&'recipe:'+i.recipe||i.kind==='other'&&'other'||'',qty:i.enteredQty??i.quantity,unit:i.enteredUnit||i.ingredient&&INGREDIENTS[i.ingredient][1]||'',confidence:'confirmed'}))};if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL='';try{const local=await localPhoto(id);if(local?.blob)receiptPhotoURL=URL.createObjectURL(local.blob);else if(r.hasPhoto&&cloudConnection.connected){const res=await familyRequest('photo&id='+encodeURIComponent(id));if(res.ok)receiptPhotoURL=URL.createObjectURL(await res.blob())}}catch(error){}receiptEditor()}
function notesImporter(text=''){notesDraft={text,rows:[],target:'shopping'};modal('Nhập từ ghi chú điện thoại',`<p class="hint">iPhone Notes / Google Keep / Samsung Notes: sao chép nội dung và dán bên dưới, hoặc xuất tệp .txt / .md / .csv rồi chọn tệp. App không tự truy cập ứng dụng ghi chú của bạn.</p><div class="field"><label for="notes-target">Bạn muốn nhập vào đâu?</label><select id="notes-target"><option value="shopping">Danh sách đi chợ</option><option value="planner">Thực đơn tuần đang xem</option><option value="recipe">Một công thức trong Kho món</option></select></div><div class="field"><label for="notes-text">Nội dung ghi chú</label><textarea id="notes-text" rows="9" placeholder="Thịt gà 500g&#10;Cà chua 1kg&#10;Trứng 6 quả">${esc(text)}</textarea></div><div class="toolbar"><button class="btn small" data-feature="notes-file">↑ Chọn tệp ghi chú</button><input type="file" id="notes-file-input" accept=".txt,.md,.csv,.text,text/plain,text/markdown,text/csv" hidden></div><p class="hint topspace">Android: khi đã cài PWA, bạn cũng có thể thử Chia sẻ văn bản → Bếp Gia Đình nếu hệ điều hành hiển thị app.</p>`,`<button class="btn" data-action="close-modal">Hủy</button><button class="btn primary" data-feature="notes-preview">Xem trước, chưa nhập</button>`,true)}
function notesPreview(){const text=$('#notes-text').value.trim();if(!text){toast('Dán nội dung trước khi xem trước.',true);return}if(text.length>100000){toast('Ghi chú tối đa 100.000 ký tự.',true);return}notesDraft.text=text;notesDraft.target=$('#notes-target').value;if(notesDraft.target==='planner'){previewPlanNotes(text);return}let rowsText=text,steps='',title='';if(notesDraft.target==='recipe'){const lines=text.split('\n').filter(s=>s.trim());title=lines.shift()?.replace(/^(tên món|ten mon)\s*:\s*/i,'').trim()||'Món từ ghi chú';const all=lines.join('\n'),split=all.search(/(?:cách nấu|cach nau|hướng dẫn|huong dan|steps|method)\s*:/i);rowsText=(split>=0?all.slice(0,split):all).replace(/^(nguyên liệu|nguyen lieu|ingredients)\s*:/im,'');steps=split>=0?all.slice(split).replace(/^[^:]+:/,'').trim():'';notesDraft.title=title;notesDraft.steps=steps}notesDraft.rows=parseShoppingNotes(rowsText,state);modal('Kiểm tra trước khi nhập',`<p class="hint">${notesDraft.target==='recipe'?'Một công thức cho 4 người: đối ứng các nguyên liệu và kiểm tra cách nấu.':'Các dòng đã đối ứng sẽ đặt lượng mua cho khoảng ngày đang xem; dòng chọn “Đồ khác” sẽ thêm riêng.'} Không thay thế toàn bộ dữ liệu.</p>${notesDraft.target==='recipe'?`<div class="field"><label for="notes-recipe-title">Tên món</label><input id="notes-recipe-title" value="${esc(title)}" maxlength="100"></div>`:''}<div id="notes-preview-rows">${notesDraft.rows.map((r,i)=>`<div class="note-import-row" data-index="${i}"><label><input type="checkbox" class="check note-include" checked><span>${esc(r.raw)}</span></label><select class="input note-match" aria-label="Đối ứng ghi chú dòng ${i+1}"><option value="">${notesDraft.target==='recipe'?'Chọn nguyên liệu':'Đồ khác / chưa đối ứng'}</option>${Object.entries(INGREDIENTS).map(([id,ing])=>`<option value="${id}" ${r.match===id?'selected':''}>${esc(ing[0])} (${ing[1]})</option>`).join('')}</select><input class="input note-qty" aria-label="Lượng ghi chú dòng ${i+1}" type="number" min="0.001" step="any" placeholder="Lượng" value="${r.qty??''}"><select class="input note-unit" aria-label="Đơn vị ghi chú dòng ${i+1}">${[['','Chưa rõ'],['g','g'],['kg','kg'],['ml','ml'],['l','lít'],['quả','quả'],['pack','gói / hộp']].map(([u,n])=>`<option value="${u}" ${r.unit===u?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}</div>${notesDraft.target==='recipe'?`<div class="field topspace"><label for="notes-recipe-steps">Cách nấu (mỗi bước một dòng)</label><textarea id="notes-recipe-steps" rows="6">${esc(steps)}</textarea></div>`:''}`,`<button class="btn" data-feature="notes-back">Sửa nội dung</button><button class="btn primary" data-feature="notes-apply">Nhập các dòng đã chọn</button>`,true)}
function previewPlanNotes(text){const result=[];for(const raw of text.split('\n').filter(s=>s.trim())){const n=normalizeText(raw),day=n.match(/(?:thu|t)\s*([2-7])\b/),sunday=/chu nhat|\bcn\b/.test(n);if(!day&&!sunday)continue;const offset=sunday?6:+day[1]-2,date=addDays(weekStart,offset),type=/\btrua\b|\blunch\b/.test(n)?'lunch':'dinner',names=raw.replace(/^[^:：]*[:：]/,'').split(/[;+]/).map(s=>s.trim()).filter(Boolean);const recipes=names.map(name=>{const found=state.recipes.find(r=>normalizeText(r.name)===normalizeText(name));return found?clone(found):{id:uid(),name,category:'main',protein:'unknown',time:0,servings:4,ingredients:[],prep:'Món nhập từ ghi chú chưa có nguyên liệu.',steps:[],custom:true}});result.push({date,type,recipes,include:true})}notesDraft.plan=result;modal('Kiểm tra thực đơn nhập',`<p class="hint">Định dạng: “Thứ 2 tối: Gà kho gừng + Canh bí xanh”. Món chưa trùng công thức chỉ nhập tên, chưa tính được nguyên liệu. Bữa khóa / đã nấu sẽ được giữ.</p>${result.map((r,i)=>`<label class="shop-row"><input type="checkbox" class="check note-plan-include" data-index="${i}" checked><span>${dayName(r.date)} ${r.type==='lunch'?'trưa':'tối'}<small>${r.recipes.map(x=>esc(x.name)+(x.ingredients.length?'':' (chưa có công thức)')).join(' + ')}</small></span></label>`).join('')||'<div class="callout">Chưa tìm thấy dòng có ngày. Hãy dùng Thứ 2…Thứ 7 hoặc Chủ Nhật, rồi ghi trưa/tối và dấu hai chấm.</div>'}`,`<button class="btn" data-feature="notes-back">Sửa nội dung</button><button class="btn primary" data-feature="notes-apply" ${!result.length?'disabled':''}>Nhập thực đơn đã chọn</button>`,true)}
function applyNotes(){const d=notesDraft;if(!d)return;if(d.target==='planner'){let count=0;$$('.note-plan-include').forEach(el=>{const p=d.plan[+el.dataset.index],m=currentWeek().days[p.date][p.type];if(el.checked&&!m.cooked&&!m.locked){m.recipes=clone(p.recipes);m.tasks={};count++}});save(`Đã nhập ${count} bữa; giữ bữa khóa / đã nấu.`);closeModal();render();return}const rows=$$('.note-import-row').filter(el=>$('.note-include',el).checked).map(el=>({raw:d.rows[+el.dataset.index].raw,match:$('.note-match',el).value,qty:$('.note-qty',el).value===''?null:+$('.note-qty',el).value,unit:$('.note-unit',el).value}));if(!rows.length){toast('Chọn ít nhất một dòng.',true);return}if(rows.some(r=>r.match&&canonicalQuantity(r.qty,r.unit,r.match)===null||d.target==='recipe'&&!r.match)){toast('Đối ứng nguyên liệu và nhập đúng lượng g/kg, ml/lít hoặc quả; bỏ tick dòng chưa dùng.',true);return}if(d.target==='recipe'){const title=$('#notes-recipe-title').value.trim(),steps=$('#notes-recipe-steps').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!title||!steps.length){toast('Điền tên món và cách nấu trước khi nhập.',true);return}state.recipes.push({id:uid(),name:title,category:'main',protein:'unknown',time:30,servings:4,ingredients:rows.map(r=>({id:r.match,qty:canonicalQuantity(r.qty,r.unit,r.match)})),prep:'Công thức nhập từ ghi chú. Kiểm tra lại khẩu phần và thời gian.',steps,custom:true,favorite:false});log('Nhập công thức từ ghi chú: '+title)}else{const[start,end]=shopDates(),sums={};for(const r of rows){if(r.match)sums[r.match]=(sums[r.match]||0)+canonicalQuantity(r.qty,r.unit,r.match);else currentWeek().extras.push({id:uid(),name:r.raw,qty:r.qty?`${r.qty} ${r.unit}`:'Theo ghi chú',cost:0,done:false})}const existing=shopping(state,currentWeek(),start,end);for(const[id,qty]of Object.entries(sums)){if(existing.some(r=>r.id===id))setPurchaseQuantity(currentWeek(),start,end,id,qty);else currentWeek().extras.push({id:uid(),name:INGREDIENTS[id][0],qty:fmtQty(qty,INGREDIENTS[id][1]),cost:qty*INGREDIENTS[id][3],done:false})}log('Nhập '+rows.length+' dòng đi chợ từ ghi chú')}save('Đã nhập các dòng được kiểm tra.');closeModal();render()}
function manageMembers(){modal('Thành viên nhà mình',`<p class="hint">Thêm người hoặc bớt đúng thành viên. Khẩu phần của các bữa chưa nấu sẽ tính lại; bữa đã nấu giữ lượng đã dùng.</p>${state.members.map(m=>`<div class="shop-row"><span>${esc(m.emoji)}</span><span class="item-label"><b>${esc(m.name)}</b><small>${m.weight} suất chuẩn / bữa</small></span><button class="btn small danger" data-action="remove-member-dialog" data-id="${m.id}" ${state.members.length<=1?'disabled':''}>Bớt người này</button></div>`).join('')}`,`<button class="btn" data-action="settings">Sửa tên / khẩu phần</button><button class="btn primary" data-action="add-member">+ Thêm người</button>`)}
const cloudConnection={available:false,configured:false,connected:false,etag:null,dirty:false,syncing:false,conflict:false,remote:null,timer:null,photoBusy:false};
async function familyRequest(op,options={}){return fetch('/.netlify/functions/family?op='+op,{credentials:'same-origin',cache:'no-store',...options,headers:{...options.headers}})}
function cloudStatusText(){return !cloudConnection.available?'Lưu trên thiết bị này':!cloudConnection.configured?'Netlify chưa đặt mật khẩu':!cloudConnection.connected?'Netlify · chưa kết nối':cloudConnection.conflict?'Có thay đổi cần đối chiếu':cloudConnection.dirty?'Chờ lưu lên Netlify':'Đã đồng bộ Netlify'}
function updateCloudStatus(){const el=$('#save-status');if(el&&!unsaved)el.textContent=cloudStatusText()}
function queueFamilySync(){if(!cloudConnection.connected){if(localStorage.getItem('bep-cloud-enabled')==='yes')localStorage.setItem('bep-cloud-pending','yes');return}cloudConnection.dirty=true;localStorage.setItem('bep-cloud-pending','yes');clearTimeout(cloudConnection.timer);cloudConnection.timer=setTimeout(()=>syncFamilyState(),900);setTimeout(updateCloudStatus,0)}
async function syncFamilyState(){if(!cloudConnection.connected||cloudConnection.syncing||cloudConnection.conflict||!cloudConnection.dirty||!navigator.onLine)return;cloudConnection.syncing=true;const serialized=JSON.stringify(state);try{const res=await familyRequest('state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:JSON.parse(serialized),etag:cloudConnection.etag})});if(res.status===409){cloudConnection.conflict=true;await loadRemoteConflict();return}if(res.status===401){cloudConnection.connected=false;toast('Phiên Netlify hết hạn. Kết nối lại để tiếp tục đồng bộ.',true);return}if(!res.ok)throw Error('Netlify chưa lưu được dữ liệu.');const result=await res.json();cloudConnection.etag=result.etag;cloudConnection.dirty=JSON.stringify(state)!==serialized;if(!cloudConnection.dirty)localStorage.removeItem('bep-cloud-pending');uploadPendingPhotos();if(cloudConnection.dirty)cloudConnection.timer=setTimeout(syncFamilyState,1000)}catch(error){toast('Đã giữ dữ liệu trên máy; đang chờ lưu lên Netlify.',true)}finally{cloudConnection.syncing=false;updateCloudStatus()}}
function persistRemoteState(data){if(!validImport(data))throw Error('Dữ liệu Netlify không đúng định dạng.');state=data;state.receipts??=[];state.aliases??={};ensureWeek(state,weekStart);localStorage.setItem(KEY,JSON.stringify(state));unsaved=false;cloudConnection.dirty=false;render();updateCloudStatus()}
async function fetchFamilyState(){const res=await familyRequest('state');if(!res.ok)throw Error('Không tải được bản Netlify.');return res.json()}
async function loadRemoteConflict(){try{const remote=await fetchFamilyState();cloudConnection.remote=remote;modal('Hai thiết bị vừa thay đổi dữ liệu',`<p>App đã dừng đồng bộ để tránh ghi đè thay đổi của người khác.</p><div class="callout">Bạn có thể xuất bản đang có trên máy để giữ lại, rồi chọn dùng bản Netlify hoặc thay bằng bản trên máy này. Không tự gộp những chỉnh sửa mâu thuẫn.</div>`,`<button class="btn" data-action="export">Xuất bản máy này</button><button class="btn" data-feature="cloud-use-remote">Dùng bản Netlify</button><button class="btn primary" data-feature="cloud-use-local">Dùng bản máy này</button>`,true)}catch(e){toast('Có xung đột; cần mạng để đối chiếu bản Netlify.',true)}}
async function cloudSettings(){modal('Lưu & dùng chung trên Netlify',`<div class="status-line"><span>Trạng thái</span><span class="pill ${cloudConnection.connected?'':'orange'}">${esc(cloudStatusText())}</span></div><p class="hint">Khi triển khai gói đầy đủ trên Netlify, dữ liệu gia đình và hóa đơn được lưu vào Netlify Blobs. Mỗi điện thoại mở cùng website rồi nhập mật khẩu gia đình để dùng chung.</p>${cloudConnection.available?cloudConnection.configured?cloudConnection.connected?'<p class="hint">Đang kết nối. Khi mất mạng, bản máy được giữ lại và chờ đồng bộ. Sửa đồng thời sẽ có màn hình chọn bản để tránh âm thầm mất dữ liệu.</p>':'<form id="cloud-login-form"><div class="field"><label for="family-password">Mật khẩu gia đình</label><input id="family-password" name="password" type="password" autocomplete="current-password" minlength="12" required></div></form>':'<div class="callout">Đặt biến môi trường FAMILY_PASSWORD (ít nhất 12 ký tự) trong Netlify, phạm vi Functions, rồi deploy lại. Không đưa mật khẩu vào HTML.</div>':'<div class="callout">Bản review hiện tại chưa chạy backend Netlify. Gói tải về có sẵn Functions và cấu hình lưu trữ. Sau khi bạn deploy lên Netlify, mở lại mục này để kết nối.</div>'}<h3>Nhập dữ liệu từ thiết bị khác</h3><p class="hint">Dùng “Nhập Notes” cho văn bản hoặc xuất/khôi phục JSON để chuyển toàn bộ dữ liệu. Ảnh receipt được giữ trên thiết bị, và được tải lên Netlify khi đã kết nối.</p>`,`<button class="btn" data-feature="notes-import">Nhập Notes</button>${cloudConnection.connected?'<button class="btn" data-feature="cloud-disconnect">Ngắt kết nối</button><button class="btn primary" data-feature="cloud-sync">Đồng bộ ngay</button>':cloudConnection.available&&cloudConnection.configured?'<button class="btn primary" data-feature="cloud-login">Kết nối</button>':''}`,true)}
async function loginFamily(){const form=$('#cloud-login-form');if(!form?.reportValidity())return;const password=$('#family-password').value;try{const res=await familyRequest('login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});if(!res.ok){toast(res.status===401?'Mật khẩu chưa đúng.':'Chưa kết nối được Netlify.',true);return}cloudConnection.connected=true;localStorage.setItem('bep-cloud-enabled','yes');const remote=await fetchFamilyState();cloudConnection.etag=remote.etag;if(!remote.state){cloudConnection.dirty=true;closeModal();await syncFamilyState();toast('Đã khởi tạo dữ liệu chung trên Netlify.');return}cloudConnection.remote=remote;cloudConnection.conflict=true;modal('Chọn dữ liệu khi kết nối',`<p>Netlify đang có ${remote.state.members?.length||0} thành viên và ${remote.state.receipts?.length||0} hóa đơn. Bản trên máy này có ${state.members.length} thành viên và ${state.receipts.length} hóa đơn.</p><p class="hint">Chọn bản muốn tiếp tục. Nên xuất bản trên máy nếu muốn giữ lại trước khi thay thế.</p>`,`<button class="btn" data-action="export">Xuất bản máy này</button><button class="btn primary" data-feature="cloud-use-remote">Dùng bản Netlify</button><button class="btn" data-feature="cloud-use-local">Dùng bản máy này</button>`,true)}catch(error){toast(error.message||'Không kết nối được Netlify.',true)}finally{updateCloudStatus()}}
async function uploadPendingPhotos(){if(!cloudConnection.connected||cloudConnection.photoBusy)return;cloudConnection.photoBusy=true;try{for(const r of state.receipts){if(!r.hasPhoto)continue;const local=await localPhoto(r.id);if(!local?.blob||local.uploaded)continue;const res=await familyRequest('photo&id='+encodeURIComponent(r.id),{method:'PUT',headers:{'Content-Type':'image/jpeg'},body:local.blob});if(!res.ok)throw Error('Ảnh chưa tải lên Netlify.');await localPhoto(r.id,{...local,uploaded:true})}}catch(error){toast('Khoản chi đã lưu; ảnh receipt còn trên máy và sẽ tải lại sau.',true)}finally{cloudConnection.photoBusy=false}}
async function checkCloud(){try{const res=await familyRequest('status');if(!res.ok||!res.headers.get('content-type')?.includes('application/json'))return;const data=await res.json();cloudConnection.available=true;cloudConnection.configured=!!data.configured;cloudConnection.connected=!!data.connected;if(data.connected){const remote=await fetchFamilyState();cloudConnection.etag=remote.etag;const pending=localStorage.getItem('bep-cloud-pending')==='yes';if(pending){cloudConnection.dirty=true;cloudConnection.conflict=true;cloudConnection.remote=remote;await loadRemoteConflict()}else if(remote.state)persistRemoteState(remote.state);else{cloudConnection.dirty=true;await syncFamilyState()}}}catch(error){}finally{updateCloudStatus()}}
// Keep only a pending marker locally; the password stays in an HttpOnly session cookie.
window.addEventListener('beforeunload',()=>{if(cloudConnection.connected&&cloudConnection.dirty)localStorage.setItem('bep-cloud-pending','yes');else localStorage.removeItem('bep-cloud-pending')});
window.addEventListener('online',()=>{if(!cloudConnection.connected)checkCloud();else{syncFamilyState();uploadPendingPhotos()}});
setInterval(async()=>{if(!cloudConnection.connected||cloudConnection.dirty||cloudConnection.syncing||cloudConnection.conflict||document.hidden||$('.modal'))return;try{const remote=await fetchFamilyState();if(remote.etag!==cloudConnection.etag&&remote.state){persistRemoteState(remote.state);cloudConnection.etag=remote.etag;toast('Đã nhận cập nhật gia đình từ Netlify.')}}catch(error){}},30000);
document.addEventListener('click',async event=>{const el=event.target.closest('[data-feature]');if(!el||el.disabled)return;const action=el.dataset.feature,id=el.dataset.id;try{switch(action){case'receipt-new':newReceipt();break;case'receipt-open':await openReceipt(id);break;case'receipt-camera':$('#receipt-camera-file').click();break;case'receipt-file':$('#receipt-gallery-file').click();break;case'receipt-parse':{collectReceipt();const parsed=parseReceiptText(receiptDraft.raw,state);receiptDraft.items=parsed.items;receiptDraft.total=parsed.total;receiptDraft.date=parsed.date;receiptDraft.store=receiptDraft.store||parsed.store;receiptEditor();break}case'receipt-add-line':collectReceipt();receiptDraft.items.push({id:uid(),label:'',total:0,match:'',qty:null,unit:'',confidence:'unknown'});$('#receipt-lines').innerHTML=receiptLineRows();updateReceiptTotals();break;case'receipt-remove-line':collectReceipt();receiptDraft.items.splice(+el.dataset.index,1);$('#receipt-lines').innerHTML=receiptLineRows();updateReceiptTotals();break;case'receipt-save':await saveReceipt();break;case'receipt-save-confirm':await saveReceipt(true);break;case'receipt-back':receiptEditor();break;case'notes-import':notesImporter();break;case'notes-file':$('#notes-file-input').click();break;case'notes-preview':notesPreview();break;case'notes-apply':applyNotes();break;case'notes-back':notesImporter(notesDraft.text);break;case'manage-members':manageMembers();break;case'cloud-settings':await cloudSettings();break;case'cloud-login':await loginFamily();break;case'cloud-use-remote':{const remote=cloudConnection.remote;if(remote?.state){persistRemoteState(remote.state);cloudConnection.etag=remote.etag;cloudConnection.conflict=false;cloudConnection.remote=null;localStorage.removeItem('bep-cloud-pending');closeModal();toast('Đang dùng bản Netlify.')}break}case'cloud-use-local':{cloudConnection.etag=cloudConnection.remote?.etag||null;cloudConnection.remote=null;cloudConnection.conflict=false;cloudConnection.dirty=true;closeModal();await syncFamilyState();break}case'cloud-sync':if(cloudConnection.conflict)await loadRemoteConflict();else{cloudConnection.dirty=true;await syncFamilyState();cloudSettings()}break;case'cloud-disconnect':await familyRequest('logout',{method:'POST'});cloudConnection.connected=false;clearTimeout(cloudConnection.timer);localStorage.removeItem('bep-cloud-pending');localStorage.removeItem('bep-cloud-enabled');updateCloudStatus();cloudSettings();break}}catch(error){toast(error.message||'Chưa thực hiện được thao tác. Hãy thử lại.',true)}});
document.addEventListener('input',e=>{if(e.target.matches('.receipt-price,#receipt-total'))updateReceiptTotals()});
document.addEventListener('change',async e=>{if(['receipt-camera-file','receipt-gallery-file'].includes(e.target.id))await readReceiptPhoto(e.target.files[0]);if(e.target.id==='notes-file-input'){const file=e.target.files[0];if(!file)return;if(file.size>1000000){toast('Tệp ghi chú tối đa 1 MB.',true);return}$('#notes-text').value=await file.text()}});
async function consumeSharedNotes(){if(location.hash!=='#import-notes'||!('caches'in window))return;try{const cache=await caches.open('bep-note-inbox');const res=await cache.match('/shared-notes-draft');if(res){const data=await res.json();await cache.delete('/shared-notes-draft');notesImporter([data.title,data.text].filter(Boolean).join('\n'))}}catch(error){toast('Chưa đọc được ghi chú chia sẻ. Bạn có thể dán trực tiếp.',true)}}
view=location.hash.slice(1)||view;render();checkCloud();consumeSharedNotes();
